// Applies Martin's Step-1 review decisions on top of the same matching logic as
// engine-import-review.mjs, re-writes scripts/fill/engine-import-review.csv with the `keep`
// column filled in, and prints the extra reports he asked for. Still fully read-only on the
// DB -- no writes. Step 2's migration SQL is generated by a separate script
// (generate-engine-import-migrations.mjs) from this same resolved data, so the two stay
// consistent by construction instead of by hand-transcription.

import { createClient } from "@supabase/supabase-js";
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL,
  process.env.SUPABASE_SERVICE_ROLE_KEY
);

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const OUT_PATH = path.join(__dirname, "engine-import-review.csv");

const RELIABILITY_MAP = { excellent: 5, good: 4, average: 3, below_average: 2, poor: 1 };
const VW_GROUP_BRANDS = new Set(["audi", "volkswagen", "škoda", "seat", "cupra"]);

// Martin's explicit Step-1 CHECK decisions -- each keys on the OLD (engine_code, power_kw)
// exactly as it appeared in the review CSV, since that's what he reviewed against.
const CHECK_REMAPS = [
  { oldCode: "CHHB", oldPowerKw: 200, targetCode: "DNUA", targetPowerKw: 200 },
  { oldCode: "CHPA", oldPowerKw: 110, targetCode: "CZDA", targetPowerKw: 110 },
  { oldCode: "CLHA", oldPowerKw: 81, targetCode: "CRKB", targetPowerKw: 81 },
  { oldCode: "CZPA", oldPowerKw: 140, targetCode: "DKZA", targetPowerKw: 140 },
  { oldCode: "DKZA", oldPowerKw: 147, targetCode: "CZPC", targetPowerKw: 147 },
  { oldCode: "DNUA", oldPowerKw: 235, targetCode: "DNFG", targetPowerKw: 235 },
  { oldCode: "CZCA", oldPowerKw: 81, action: "skip" },
];

// Audi A3 (8Y) EA211 Evo 110kW AMBIGUOUS row: DFYA (eTSI mild-hybrid) if the old text mentions
// it, else DADA (plain Evo). Confirmed live: the old row's own pros text says "48V mild-hybrid"
// outright.
const MILD_HYBRID_RE = /etsi|48v|mild.?hybrid/i;

async function fetchAllRows(table, select) {
  const pageSize = 1000;
  const rows = [];
  let from = 0;
  while (true) {
    const { data, error } = await supabase.from(table).select(select).range(from, from + pageSize - 1);
    if (error) throw error;
    rows.push(...(data || []));
    if (!data || data.length < pageSize) break;
    from += pageSize;
  }
  return rows;
}

function parseGenCode(model) {
  const m = model.match(/\(([^)]+)\)\s*$/);
  return m ? m[1] : null;
}

function csvField(value) {
  const s = String(value ?? "");
  if (/[",\n]/.test(s)) return `"${s.replace(/"/g, '""')}"`;
  return s;
}

async function main() {
  const [vehicles, engines, catalogEngines, catalogPhases, catalogModels, catalogBrands, configs] = await Promise.all([
    fetchAllRows("vehicles", "id, brand, model"),
    fetchAllRows("engines", "*"),
    fetchAllRows("catalog_engines", "id, code, alt_codes, power_kw, fuel_type, displacement_cc"),
    fetchAllRows("catalog_phases", "id, model_id, generation_code"),
    fetchAllRows("catalog_models", "id, brand_id, name"),
    fetchAllRows("catalog_brands", "id, name"),
    fetchAllRows("catalog_vehicle_configurations", "phase_id, engine_id"),
  ]);

  const vehicleById = new Map(vehicles.map((v) => [v.id, v]));
  const modelById = new Map(catalogModels.map((m) => [m.id, m]));
  const brandById = new Map(catalogBrands.map((b) => [b.id, b]));
  const catalogEngineById = new Map(catalogEngines.map((e) => [e.id, e]));
  const catalogEngineByCodePower = new Map(catalogEngines.map((e) => [`${e.code.toUpperCase()}@${e.power_kw}`, e]));

  const phasesByBrandGen = new Map();
  const phaseBrandGenOf = new Map(); // phase_id -> "brandlower::GENCODE" (for the reverse lookup)
  for (const phase of catalogPhases) {
    const model = modelById.get(phase.model_id);
    const brand = model && brandById.get(model.brand_id);
    if (!brand || !phase.generation_code) continue;
    const key = `${brand.name.toLowerCase()}::${phase.generation_code.toUpperCase()}`;
    const list = phasesByBrandGen.get(key) ?? [];
    list.push(phase.id);
    phasesByBrandGen.set(key, list);
    phaseBrandGenOf.set(phase.id, key);
  }

  const engineIdsByPhase = new Map();
  const phaseIdsByEngine = new Map();
  for (const c of configs) {
    const eset = engineIdsByPhase.get(c.phase_id) ?? new Set();
    eset.add(c.engine_id);
    engineIdsByPhase.set(c.phase_id, eset);
    const pset = phaseIdsByEngine.get(c.engine_id) ?? new Set();
    pset.add(c.phase_id);
    phaseIdsByEngine.set(c.engine_id, pset);
  }

  const byCode = new Map();
  for (const ce of catalogEngines) {
    const codes = [ce.code, ...(ce.alt_codes || [])].map((c) => c.toUpperCase().trim());
    for (const c of codes) {
      const list = byCode.get(c) ?? [];
      list.push(ce);
      byCode.set(c, list);
    }
  }

  // Every catalog_phases id this old vehicle's brand+generation-code resolves to (same
  // parse/lookup as the L2 matching pass) -- used both by generationMatchesEngineUsage below
  // and by the Migration B generator, which needs it for EVERY matched row (not just L2 ones)
  // to scope its consumption pre-fill to the right phase(s).
  function resolveVehiclePhaseIds(vehicle) {
    if (!vehicle) return [];
    const genCode = parseGenCode(vehicle.model);
    if (!genCode) return [];
    const pieces = genCode.includes("/") ? genCode.split("/").map((s) => s.trim()) : [genCode];
    const brandLower = vehicle.brand.toLowerCase();
    return pieces.flatMap((piece) => phasesByBrandGen.get(`${brandLower}::${piece.toUpperCase()}`) || []);
  }

  // Does this old row's vehicle generation resolve to a phase that actually uses `engine`?
  function generationMatchesEngineUsage(vehicle, engine) {
    if (!vehicle || !engine) return false;
    const phaseIds = resolveVehiclePhaseIds(vehicle);
    const usingPhases = phaseIdsByEngine.get(engine.id) || new Set();
    return phaseIds.some((pid) => usingPhases.has(pid));
  }

  // ---- Pass 1: same L1/L2/L3-CHECK/AMBIGUOUS/UNMATCHED matching as engine-import-review.mjs ----
  const rows = [];
  for (const e of engines) {
    const vehicle = vehicleById.get(e.vehicle_id);
    const vehicleLabel = vehicle ? `${vehicle.brand} ${vehicle.model}` : `(unknown vehicle ${e.vehicle_id})`;
    const oldCode = (e.engine_code || "").trim().toUpperCase();

    let outcome = "UNMATCHED";
    let matchedEngine = null;
    let candidateEngines = [];

    if (oldCode && byCode.has(oldCode)) {
      const candidates = byCode.get(oldCode);
      const powerMatch = candidates.find((ce) => ce.power_kw === e.power_kw);
      if (powerMatch) { outcome = "L1"; matchedEngine = powerMatch; }
      else { outcome = "L3-CHECK"; candidateEngines = candidates; }
    }

    if (outcome === "UNMATCHED" && vehicle) {
      const genCode = parseGenCode(vehicle.model);
      if (genCode) {
        const pieces = genCode.includes("/") ? genCode.split("/").map((s) => s.trim()) : [genCode];
        const brandLower = vehicle.brand.toLowerCase();
        const phaseIds = pieces.flatMap((piece) => phasesByBrandGen.get(`${brandLower}::${piece.toUpperCase()}`) || []);
        const candidateIds = new Set();
        for (const pid of phaseIds) for (const eid of engineIdsByPhase.get(pid) || []) candidateIds.add(eid);
        const oldFuel = (e.fuel_type || "").toLowerCase();
        const l2Matches = [...candidateIds]
          .map((id) => catalogEngineById.get(id))
          .filter((ce) => ce && ce.power_kw === e.power_kw && ce.fuel_type.toLowerCase() === oldFuel &&
            (e.displacement_cc == null || ce.displacement_cc == null || ce.displacement_cc === e.displacement_cc));
        const uniqueL2 = [...new Map(l2Matches.map((c) => [c.id, c])).values()];
        if (uniqueL2.length === 1) { outcome = "L2"; matchedEngine = uniqueL2[0]; }
        else if (uniqueL2.length > 1) { outcome = "AMBIGUOUS"; candidateEngines = uniqueL2; }
      }
    }

    const relRaw = e.reliability_rating || "";
    rows.push({
      outcome, matchedEngine, candidateEngines, vehicle, vehicleLabel,
      oldEngineCode: e.engine_code || "", oldLabel: e.label || "", oldPowerKw: e.power_kw,
      oldReliabilityRaw: relRaw, reliabilityMapped: RELIABILITY_MAP[relRaw.toLowerCase()] ?? "",
      pros: e.pros || [], cons: e.cons || [], commonFaults: e.common_faults || [],
      oldFuelConsumptionAvg: e.fuel_consumption_avg ?? null,
      oldBatteryKwh: e.battery_kwh ?? null,
      // Resolved once per row, used by generationMatchesEngineUsage above AND by Migration
      // B's per-config consumption pre-fill (which needs it for every matched row, not just
      // the L2 ones that happened to need it during matching).
      phaseIds: resolveVehiclePhaseIds(vehicle),
      keep: "", note: "",
    });
  }

  // ---- Pass 2: apply Martin's CHECK remaps ----
  for (const r of rows) {
    if (r.outcome !== "L3-CHECK") continue;
    const oldCode = r.oldEngineCode.trim().toUpperCase();
    const remap = CHECK_REMAPS.find((m) => m.oldCode === oldCode && m.oldPowerKw === r.oldPowerKw);
    if (!remap) continue; // unreviewed CHECK row -- stays undecided
    if (remap.action === "skip") {
      r.keep = "n";
      r.note = "Martin: skip -- no catalog phase for this car/engine yet.";
      continue;
    }
    const target = catalogEngineByCodePower.get(`${remap.targetCode}@${remap.targetPowerKw}`);
    if (!target) {
      r.note = `ERROR: remap target ${remap.targetCode}@${remap.targetPowerKw} not found live -- left undecided.`;
      continue;
    }
    r.outcome = "L3-CHECK-RESOLVED";
    r.matchedEngine = target;
    r.keep = "y";
    r.note = `Martin: remapped from ${oldCode}@${r.oldPowerKw}.`;
  }

  // ---- Pass 3: resolve the AMBIGUOUS A3 8Y EA211 Evo row by keyword ----
  for (const r of rows) {
    if (r.outcome !== "AMBIGUOUS") continue;
    const text = [...r.pros, ...r.cons, ...r.commonFaults].join(" · ");
    const wantCode = MILD_HYBRID_RE.test(text) ? "DFYA" : "DADA";
    const target = r.candidateEngines.find((ce) => ce.code.toUpperCase() === wantCode);
    if (target) {
      r.outcome = "AMBIGUOUS-RESOLVED";
      r.matchedEngine = target;
      r.keep = "y";
      r.note = `Martin's rule: ${MILD_HYBRID_RE.test(text) ? "mentions eTSI/48V/mild-hybrid" : "no mild-hybrid mention"} -> ${wantCode}.`;
    } else {
      r.note = `ERROR: rule picked ${wantCode} but it wasn't one of the AMBIGUOUS candidates -- left undecided.`;
    }
  }

  // ---- Pass 4: conflicting-variant resolution (pros/cons winner by generation match; faults always unioned) ----
  const byMatchedEngine = new Map();
  for (const r of rows) {
    if (!r.matchedEngine) continue;
    const list = byMatchedEngine.get(r.matchedEngine.id) ?? [];
    list.push(r);
    byMatchedEngine.set(r.matchedEngine.id, list);
  }

  const stillUndecidedGroups = [];
  for (const group of byMatchedEngine.values()) {
    if (group.length < 2) { if (group.length === 1 && !group[0].keep) group[0].keep = "y"; continue; }
    group.sort((a, b) => a.vehicleLabel.localeCompare(b.vehicleLabel) || a.oldLabel.localeCompare(b.oldLabel));
    const signature = (r) => JSON.stringify({ rel: r.reliabilityMapped, pros: [...r.pros].sort(), cons: [...r.cons].sort() });
    const distinctSignatures = new Set(group.map(signature));

    if (distinctSignatures.size === 1) {
      // No real conflict -- identical pros/cons/reliability across old rows, nothing to pick.
      group.forEach((r) => { if (!r.keep) r.keep = "y"; });
      continue;
    }

    group.forEach((r, i) => { r.variant = i + 1; });
    const engine = group[0].matchedEngine;
    const generationMatches = group.filter((r) => generationMatchesEngineUsage(r.vehicle, engine));

    if (generationMatches.length === 1) {
      const winner = generationMatches[0];
      group.forEach((r) => {
        if (r === winner) { r.keep = "y"; r.note = (r.note ? r.note + " " : "") + "Winner: generation matches a catalog phase using this engine."; }
        else { r.keep = "n"; r.note = (r.note ? r.note + " " : "") + "Superseded by the generation-matched variant (pros/cons only -- its faults still union in)."; }
      });
    } else {
      group.forEach((r) => {
        r.note = (r.note ? r.note + " " : "") + (generationMatches.length === 0
          ? "UNDECIDED: no variant's generation matches a catalog phase using this engine."
          : `UNDECIDED: ${generationMatches.length} variants' generations all match -- pick one.`);
      });
      stillUndecidedGroups.push({ engine: `${engine.code}@${engine.power_kw}`, rows: group });
    }
  }

  // ---- Write the resolved CSV (same columns as Step 1, plus `note`) ----
  const OUTCOME_ORDER = { L1: 0, L2: 1, "L3-CHECK-RESOLVED": 2, "AMBIGUOUS-RESOLVED": 3, "L3-CHECK": 4, AMBIGUOUS: 5, UNMATCHED: 6 };
  const sorted = [...rows].sort((a, b) =>
    OUTCOME_ORDER[a.outcome] - OUTCOME_ORDER[b.outcome] ||
    (a.matchedEngine ? `${a.matchedEngine.code}@${a.matchedEngine.power_kw}` : "").localeCompare(b.matchedEngine ? `${b.matchedEngine.code}@${b.matchedEngine.power_kw}` : "") ||
    a.vehicleLabel.localeCompare(b.vehicleLabel) || a.oldLabel.localeCompare(b.oldLabel)
  );

  const header = ["catalog_engine", "match_level", "old_vehicle", "old_engine_code", "old_label", "old_power_kw", "old_reliability_rating", "reliability_mapped", "pros", "cons", "common_faults", "variant", "keep", "note"];
  const lines = [header.join(",")];
  for (const r of sorted) {
    const label = r.matchedEngine ? `${r.matchedEngine.code}@${r.matchedEngine.power_kw}` : r.candidateEngines.map((c) => `${c.code}@${c.power_kw}`).join(" | ");
    lines.push([
      csvField(label), csvField(r.outcome), csvField(r.vehicleLabel), csvField(r.oldEngineCode), csvField(r.oldLabel),
      csvField(r.oldPowerKw), csvField(r.oldReliabilityRaw), csvField(r.reliabilityMapped),
      csvField(r.pros.join("; ")), csvField(r.cons.join("; ")), csvField(r.commonFaults.join("; ")),
      csvField(r.variant ?? ""), csvField(r.keep), csvField(r.note),
    ].join(","));
  }
  writeFileSync(OUT_PATH, lines.join("\n") + "\n");
  console.log(`Wrote ${OUT_PATH} (${sorted.length} rows, keep pre-filled per Martin's decisions)\n`);

  // ---- Report: rows still undecided -- genuine open decisions only (an unreviewed
  // L3-CHECK/AMBIGUOUS, or a conflicting-variant group where generation-matching didn't land
  // on exactly one winner). Plain UNMATCHED rows also have a blank `keep` but aren't a
  // "decision pending" -- they're "no catalog_ data exists yet," reported separately below.
  const undecided = rows.filter((r) => !r.keep && (r.outcome === "L3-CHECK" || r.outcome === "AMBIGUOUS" || (r.note && r.note.includes("UNDECIDED"))));
  console.log(`=== Still undecided: ${undecided.length} rows (excludes ${rows.filter((r) => !r.keep).length - undecided.length} plain UNMATCHED rows, reported separately below) ===`);
  for (const r of undecided) {
    console.log(`  [${r.outcome}] ${r.vehicleLabel} | ${r.oldEngineCode || "(no code)"} ${r.oldPowerKw}kW -> ${r.matchedEngine ? `${r.matchedEngine.code}@${r.matchedEngine.power_kw}` : r.candidateEngines.map((c) => `${c.code}@${c.power_kw}`).join(" | ") || "(no candidate)"} :: ${r.note}`);
  }

  // ---- Report: UNMATCHED rows that ARE VW-Group brands, grouped by car ----
  const vwUnmatched = rows.filter((r) => r.outcome === "UNMATCHED" && r.vehicle && VW_GROUP_BRANDS.has(r.vehicle.brand.toLowerCase()));
  const byCar = new Map();
  for (const r of vwUnmatched) {
    const list = byCar.get(r.vehicleLabel) ?? [];
    list.push(r);
    byCar.set(r.vehicleLabel, list);
  }
  console.log(`\n=== UNMATCHED rows for VW-Group brands (no catalog_ row exists yet): ${vwUnmatched.length} rows across ${byCar.size} cars ===`);
  for (const [car, list] of [...byCar.entries()].sort((a, b) => a[0].localeCompare(b[0]))) {
    console.log(`  ${car}:`);
    for (const r of list) console.log(`    ${r.oldEngineCode || "(no code)"} ${r.oldPowerKw}kW -- ${r.oldLabel}`);
  }

  // ---- Report: DKZA@140 vs DKZA@150 usage (read-only, no change) ----
  const dkza140 = catalogEngineByCodePower.get("DKZA@140");
  const dkza150 = catalogEngineByCodePower.get("DKZA@150");
  console.log(`\n=== DKZA usage (informational only, no change) ===`);
  for (const [label, eng] of [["DKZA@140", dkza140], ["DKZA@150", dkza150]]) {
    if (!eng) { console.log(`  ${label}: not found live`); continue; }
    const phaseIds = [...(phaseIdsByEngine.get(eng.id) || [])];
    console.log(`  ${label} (engine id ${eng.id}): used by ${phaseIds.length} phase(s)`);
    for (const pid of phaseIds) {
      const phase = catalogPhases.find((p) => p.id === pid);
      const model = modelById.get(phase.model_id);
      const brand = brandById.get(model.brand_id);
      console.log(`    ${brand.name} ${model.name} (${phase.generation_code})`);
    }
  }

  // Stash resolved rows for the migration generator to reuse without recomputation.
  writeFileSync(
    path.join(__dirname, ".engine-import-resolved.json"),
    JSON.stringify(rows.map((r) => ({
      outcome: r.outcome,
      matchedEngineId: r.matchedEngine ? r.matchedEngine.id : null,
      matchedEngineLabel: r.matchedEngine ? `${r.matchedEngine.code}@${r.matchedEngine.power_kw}` : null,
      vehicleLabel: r.vehicleLabel,
      oldLabel: r.oldLabel,
      reliabilityMapped: r.reliabilityMapped,
      pros: r.pros, cons: r.cons, commonFaults: r.commonFaults,
      oldFuelConsumptionAvg: r.oldFuelConsumptionAvg,
      oldBatteryKwh: r.oldBatteryKwh,
      phaseIds: r.phaseIds,
      keep: r.keep,
    })))
  );
}

main().catch((err) => { console.error(err); process.exit(1); });
